  "test_path": "tests/unit/test_observe_ignore_exceptions.py",
  "test": "import pytest
from langfuse import observe

def test_observe_raises_by_default(langfuse_memory_client, memory_exporter):
    @observe(name="error_func")
    def bad_func():
        raise ValueError("boom")
    with pytest.raises(ValueError):
        bad_func()
    # No span should be marked as error because exception propagates
    langfuse_memory_client.flush()
    span = [s for s in memory_exporter.get_finished_spans() if s.name == "error_func"][0]
    assert span.attributes.get('error') is None  # error attribute is set only on span update, not on raise

def test_observe_ignore_exceptions_swallows_error(langfuse_memory_client, memory_exporter):
    @observe(name="ignored_error", ignore_exceptions=True)
    def bad_func():
        raise RuntimeError("oops")
    # Should not raise
    result = bad_func()
    assert result is None
    langfuse_memory_client.flush()
    span = [s for s in memory_exporter.get_finished_spans() if s.name == "ignored_error"][0]
    # Span should have been ended without re‑raising; ensure it's recorded
    assert span is not None"
}
